  ctx.textAlign = 'right'; ctx.fillStyle = '#a4c6c7'; ctx.font = '11px sans-serif'; ctx.fillText(view.total ? `${view.completed}/${view.total} Todo 完成` : '暂无 Todo', 464, 18)
