    for (const e of g.enemies) { if (e.aim && (!finite(e.aim.x) || !finite(e.aim.y))) return null; if (e.age !== undefined && !finite(e.age)) return null; if (e.boss && (!finite(e.maxHP) || e.maxHP <= 0)) return null }
